const ELEVATIONS_BASE64 = "";

function decodeElevations(): number[] {
  const bytes = Uint8Array.from(atob(ELEVATIONS_BASE64), (character) => character.charCodeAt(0));
  const view = new DataView(bytes.buffer);
  return Array.from({ length: bytes.byteLength / 2 }, (_, index) => view.getUint16(index * 2, true) / 10);
}

/** 2 km square centred on the published Askervein hilltop coordinate. */
export const ASKERVEIN_TERRAIN = {
  siteId: "askervein-copernicus-glo30",
  latitude: 57.1879528,
  longitude: -7.3791861,
  columns: 33,
  rows: 33,
  cellSizeM: 62.5,
  elevationsM: decodeElevations(),
} as const;

export const ASKERVEIN_LAYOUT = {
  rows: 2,
  columns: 2,
  rotorDiameterM: 112,
  hubHeightM: 100,
  crosswindSpacingD: 6,
  downwindSpacingD: 8,
  bearingDeg: 210,
} as const;

export const ASKERVEIN_FIELD_REQUEST = {
  terrain: {
    site_id: ASKERVEIN_TERRAIN.siteId,
    origin_easting_m: 0,
    origin_northing_m: 0,
    columns: ASKERVEIN_TERRAIN.columns,
    rows: ASKERVEIN_TERRAIN.rows,
    cell_size_easting_m: ASKERVEIN_TERRAIN.cellSizeM,
    cell_size_northing_m: ASKERVEIN_TERRAIN.cellSizeM,
    elevations_m: ASKERVEIN_TERRAIN.elevationsM,
  },
  layout: {
    turbine: "vestas-v112-3450",
    rows: ASKERVEIN_LAYOUT.rows,
    columns: ASKERVEIN_LAYOUT.columns,
    crosswind_spacing_d: ASKERVEIN_LAYOUT.crosswindSpacingD,
    downwind_spacing_d: ASKERVEIN_LAYOUT.downwindSpacingD,
    hub_height_m: ASKERVEIN_LAYOUT.hubHeightM,
    // Pinned to the design bearing while the wind turns (D26). Omit it and the server
    // orients the array to whatever direction is being asked about, which presents identical
    // geometry at every bearing — no wake relation ever changes, and T3 has no answer.
    orientation_bearing_deg: ASKERVEIN_LAYOUT.bearingDeg,
    origin_easting_m: 1000,
    origin_northing_m: 1000,
  },
  wind: { bearing_deg: ASKERVEIN_LAYOUT.bearingDeg, speed_ms: 10, turbulence_intensity: 0.08 },
  volume: { levels: 8, top_elevation_m: 500 },
};
